          "Veto a la regulación de estas materias mediante Real Decreto-Ley",
          "Prohibición del desarrollo mediante Real Decreto Legislativo de la Sección 1ª del Capítulo II del Título I",
          "Necesidad de ratificación mediante referéndum de cualquier ley que desarrolle un derecho fundamental"
