          "El Estado se somete totalmente al Derecho común de sus actos, sin ostentar una especial situación jurídica, es decir, al Derecho Común y no al Especial",
          "El Estado se somete totalmente al Derecho, pero conservando una situación de prerrogativa propia del régimen administrativo",
