          "Aquel sector de la Administración Pública integrado por Entes públicos menores de carácter no territorial.",
          "El conjunto de fórmulas organizativas dotadas de personalidad jurídico-privada de que se sirven los entes públicos para huir del Derecho Administrativo común.",
